#!/usr/bin/env bash
set -euo pipefail

# PlaySpotStore HQ image pack installer for GitHub Codespaces.
# Replaces existing low-quality WebP assets without touching product JSON or application logic.

cd "$(git rev-parse --show-toplevel 2>/dev/null)" || {
  echo 'ERROR: Open the PlaySpotStore repository in Codespaces first.' >&2
  exit 1
}
if [[ "$(git branch --show-current)" != "main" ]]; then
  echo 'ERROR: Please switch to main first: git switch main' >&2
  exit 1
fi
case "$(git remote get-url origin)" in
 *dragoshelemenet/playspotstore*) ;;
 *) echo 'ERROR: This is not dragoshelemenet/playspotstore.' >&2; exit 1;;
esac
if [[ -n "$(git status --porcelain -- index.html ru.html neon-v2.css neon-assets/)" ]]; then
  echo 'ERROR: Unsaved changes in website or image files. Commit/stash these first.' >&2
  git status --short -- index.html ru.html neon-v2.css neon-assets/
  exit 1
fi
printf '\n=== PLAYSPOTSTORE HQ IMAGE UPGRADE ===\n'
echo 'Syncing with GitHub main...'
git pull --ff-only origin main
python3 - <<'PYHQ'
