expected = ('neon-hero-v2.webp','ps4.webp','ps5.webp','nintendo.webp',
            'xbox.webp','console.webp','accessories.webp')
with ZipFile(BytesIO(blob)) as zipf:
    assets={name:zipf.read('neon-assets/'+name) for name in expected}

for name,data in assets.items():
    if not data.startswith(b'RIFF') or data[8:12] != b'WEBP' or len(data)>300000:
        raise SystemExit(f'Invalid/oversized WebP for {name}; nothing changed.')

# Preflight both languages before touching any files.
updated={}
for page in ('index.html','ru.html'):
    path=Path(page)
    html=path.read_text(encoding='utf-8')
    if 'neon-assets/neon-hero-v2.webp' not in html or 'neon-v2.css' not in html:
        raise SystemExit(f'{page} does not contain Neon V2; no files changed. Install Neon V2 first.')
    for name in expected:
        pattern=r'(?P<attr>(?:src|href)=")neon-assets/'+re.escape(name)+r'(?:\?[^"<>]*)?(?=")'
        html,n=re.subn(pattern,lambda m:m.group('attr')+'neon-assets/'+name+'?v=hq-20261104',html)
        if n==0:
            raise SystemExit(f'Expected image {name} was not referenced in {page}; no files changed.')
    # Set real intrinsic hero dimensions for the optimized image.
    html=re.sub(r'(<img\s+src="neon-assets/neon-hero-v2\.webp\?v=hq-20261104"[^>]*?)\swidth="\d+"\sheight="\d+"',
                r'\g<1> width="1500" height="612"',html,count=1)
    updated[page]=html

css_path=Path('neon-v2.css')
css=css_path.read_text(encoding='utf-8')
if 'mix-blend-mode:screen' in css:
    css=css.replace('mix-blend-mode:screen;filter:brightness(1.12) contrast(1.08) saturate(1.14) drop-shadow(0 0 13px var(--glow));',
                    'mix-blend-mode:normal;filter:drop-shadow(0 0 13px var(--glow));')
    css=css.replace('mix-blend-mode:screen','mix-blend-mode:normal')

Path('neon-assets').mkdir(exist_ok=True)
for name,data in assets.items():
    Path('neon-assets',name).write_bytes(data)
    print(f'  ✓ {name}: {len(data)/1000:.1f} KB')
for name,html in updated.items():
    Path(name).write_text(html,encoding='utf-8')
    print(f'  ✓ {name}: links refreshed to bypass old browser cache')
css_path.write_text(css,encoding='utf-8')
print('  ✓ CSS: transparent product images no longer washed out by screen blending')
print('  ✓ All product JSON, catalog and search logic unchanged')
PYHQ

git add -- index.html ru.html neon-v2.css neon-assets/neon-hero-v2.webp neon-assets/ps4.webp neon-assets/ps5.webp neon-assets/nintendo.webp neon-assets/xbox.webp neon-assets/console.webp neon-assets/accessories.webp
if git diff --cached --quiet; then
    echo 'Already installed — nothing to commit.'
    exit 0
fi
printf '\nSummary of updates:\n'
git diff --cached --stat

git -c user.name='PlaySpotStore Design' -c user.email='playspotstore-update@users.noreply.github.com' commit -m 'Upgrade gaming artwork to optimized high-quality transparent WebP'
echo 'Pushing to GitHub main...'
if git push origin main; then
    echo 'SUCCESS: HQ images deployed to GitHub main.'
    echo 'Refresh https://playstationspot.store/ after GitHub Pages finishes deploying.'
else
    echo 'Push failed; your changes are safely committed locally. Retry: git push origin main'
    exit 1
fi
